//! Data type table of namespace 0 (services included), generated by
//! `tools/gen_types.py` into `data/types.bin`: supertypes, encodings and
//! definitions, for the JSON encoding (see [`crate::json`]).

use std::collections::HashMap;
use std::sync::OnceLock;

/// How a data type is encoded.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Structure,
    StructureWithOptionalFields,
    Union,
    Enumeration,
    /// No definition: a built-in type, an abstract type or a subtype of a
    /// built-in type (Duration, UtcTime, ...).
    Other,
}

pub struct Field {
    pub name: Box<str>,
    pub data_type: u32,
    pub value_rank: i32,
    pub optional: bool,
}

pub struct DataType {
    pub id: u32,
    pub supertype: u32,
    pub binary_encoding: u32,
    pub json_encoding: u32,
    pub kind: Kind,
    pub name: Box<str>,
    pub fields: Box<[Field]>,
    /// Enumerations: (name, value).
    pub values: Box<[(Box<str>, i64)]>,
}

pub struct Types {
    by_id: HashMap<u32, DataType>,
    /// Binary or JSON encoding id -> data type id.
    by_encoding: HashMap<u32, u32>,
}

static DATA: &[u8] = include_bytes!("../data/types.bin");

impl Types {
    /// The table, decoded on first use.
    pub fn get() -> &'static Types {
        static T: OnceLock<Types> = OnceLock::new();
        T.get_or_init(|| Types::parse(DATA).expect("data/types.bin is valid"))
    }

    fn parse(d: &[u8]) -> Option<Types> {
        let mut at = 0usize;
        let mut take = |n: usize| -> Option<&[u8]> {
            let s = d.get(at..at + n)?;
            at += n;
            Some(s)
        };
        if take(4)? != b"FUAT" {
            return None;
        }
        let u32_ = |b: &[u8]| u32::from_le_bytes(b.try_into().unwrap());
        let count = u32_(take(4)?);
        let mut by_id = HashMap::with_capacity(count as usize);
        let mut by_encoding = HashMap::new();
        for _ in 0..count {
            let id = u32_(take(4)?);
            let supertype = u32_(take(4)?);
            let binary_encoding = u32_(take(4)?);
            let json_encoding = u32_(take(4)?);
            let kind = match take(1)?[0] {
                0 => Kind::Structure,
                1 => Kind::StructureWithOptionalFields,
                2 => Kind::Union,
                3 => Kind::Enumeration,
                _ => Kind::Other,
            };
            let n = u16::from_le_bytes(take(2)?.try_into().unwrap()) as usize;
            let name: Box<str> = std::str::from_utf8(take(n)?).ok()?.into();
            let count = u16::from_le_bytes(take(2)?.try_into().unwrap());
            let (mut fields, mut values) = (Vec::new(), Vec::new());
            for _ in 0..count {
                let n = u16::from_le_bytes(take(2)?.try_into().unwrap()) as usize;
                let fname: Box<str> = std::str::from_utf8(take(n)?).ok()?.into();
                if kind == Kind::Enumeration {
                    values.push((fname, i64::from_le_bytes(take(8)?.try_into().unwrap())));
                } else {
                    let data_type = u32_(take(4)?);
                    let value_rank = i32::from_le_bytes(take(4)?.try_into().unwrap());
                    let optional = take(1)?[0] != 0;
                    fields.push(Field { name: fname, data_type, value_rank, optional });
                }
            }
            if binary_encoding != 0 {
                by_encoding.insert(binary_encoding, id);
            }
            if json_encoding != 0 {
                by_encoding.insert(json_encoding, id);
            }
            by_id.insert(
                id,
                DataType {
                    id,
                    supertype,
                    binary_encoding,
                    json_encoding,
                    kind,
                    name,
                    fields: fields.into(),
                    values: values.into(),
                },
            );
        }
        Some(Types { by_id, by_encoding })
    }

    pub fn by_id(&self, id: u32) -> Option<&DataType> {
        self.by_id.get(&id)
    }

    /// The data type of a binary or JSON encoding id.
    pub fn by_encoding(&self, encoding: u32) -> Option<&DataType> {
        self.by_encoding.get(&encoding).and_then(|id| self.by_id.get(id))
    }

    /// The built-in type (1..=25) a data type is encoded as: itself, or its
    /// first built-in supertype (enumerations are Int32, structures 22).
    pub fn builtin(&self, mut id: u32) -> u32 {
        for _ in 0..32 {
            if (1..=25).contains(&id) {
                return id;
            }
            let Some(t) = self.by_id(id) else { return 22 };
            match t.kind {
                Kind::Enumeration => return 6,
                Kind::Structure | Kind::StructureWithOptionalFields | Kind::Union => return 22,
                Kind::Other => id = t.supertype,
            }
        }
        22
    }
}

// ------------------------------------------------------------- transcoding

use crate::codec::{Reader, Writer};
use crate::types::{decode_base64, format_guid, parse_guid, ExpandedNodeId, NodeId};
use serde_json::{Map, Number, Value};
use std::sync::Arc;

/// Content type of the JSON encoding over HTTPS (Part 6 §7.4.5).
pub const CONTENT_TYPE: &str = "application/json";

/// 100 ns ticks from 1601-01-01 to 1970-01-01.
const UNIX_EPOCH_TICKS: i64 = 116_444_736_000_000_000;

/// Nesting limit of JSON values and binary structures.
const MAX_DEPTH: u32 = 64;

type JResult<T> = Result<T, String>;

/// Converts between the OPC UA JSON compact encoding (Part 6 §5.4) and the
/// binary encoding, driven by the data type table: the service layer only
/// ever sees binary messages. NodeIds of namespaces other than 0 use their
/// namespace URI (`nsu=`); `ns=` is accepted too.
pub struct Transcoder<'a> {
    types: &'static Types,
    namespaces: &'a [Arc<str>],
}

impl<'a> Transcoder<'a> {
    pub fn new(namespaces: &'a [Arc<str>]) -> Transcoder<'a> {
        Transcoder { types: Types::get(), namespaces }
    }

    // ------------------------------------------------- JSON -> binary

    /// A JSON message (an ExtensionObject: `TypeId` and `Body`) to its
    /// binary encoding: the type's binary encoding NodeId, then the body.
    pub fn message_to_binary(&self, json: &[u8], out: &mut Vec<u8>) -> JResult<()> {
        let v: Value = serde_json::from_slice(json).map_err(|e| format!("invalid JSON: {e}"))?;
        let obj = v.as_object().ok_or("the message is not a JSON object")?;
        let id = eo_field(obj, "TypeId").and_then(Value::as_str).ok_or("the message has no TypeId")?;
        let t = self.message_type(id)?;
        let mut w = Writer::new(out);
        w.node_id(&NodeId::ns0(t.binary_encoding));
        self.write_structure(t, eo_field(obj, "Body"), &mut w, 0)
    }

    fn message_type(&self, id: &str) -> JResult<&'static DataType> {
        match self.node_id(id)? {
            NodeId::Numeric(0, n) => self
                .types
                .by_id(n)
                .filter(|t| t.binary_encoding != 0)
                .or_else(|| self.types.by_encoding(n))
                .ok_or_else(|| format!("unknown message type {id}")),
            _ => Err(format!("unknown message type {id}")),
        }
    }

    fn write_value(&self, v: Option<&Value>, data_type: u32, rank: i32, w: &mut Writer, depth: u32) -> JResult<()> {
        if depth > MAX_DEPTH {
            return Err("nested too deeply".into());
        }
        if rank >= 0 {
            match v {
                None | Some(Value::Null) => w.i32(-1),
                Some(Value::Array(items)) => {
                    w.i32(items.len() as i32);
                    for item in items {
                        self.write_scalar(Some(item), data_type, w, depth + 1)?;
                    }
                }
                Some(_) => return Err("an array was expected".into()),
            }
            return Ok(());
        }
        self.write_scalar(v, data_type, w, depth)
    }

    fn write_scalar(&self, v: Option<&Value>, data_type: u32, w: &mut Writer, depth: u32) -> JResult<()> {
        let v = v.filter(|v| !v.is_null());
        if let Some(t) = self.types.by_id(data_type) {
            match t.kind {
                Kind::Structure | Kind::StructureWithOptionalFields | Kind::Union => {
                    return self.write_structure(t, v, w, depth + 1)
                }
                Kind::Enumeration => {
                    w.i32(enum_value(t, v)?);
                    return Ok(());
                }
                Kind::Other => {}
            }
        }
        // The abstract Enumeration is an Int32 in a structure.
        let builtin = if data_type == 29 { 6 } else { self.types.builtin(data_type) };
        self.write_builtin(builtin, v, w, depth)
    }

    fn write_structure(&self, t: &DataType, v: Option<&Value>, w: &mut Writer, depth: u32) -> JResult<()> {
        let empty = Map::new();
        let obj = match v {
            None | Some(Value::Null) => &empty,
            Some(Value::Object(o)) => o,
            Some(_) => return Err(format!("{} must be a JSON object", t.name)),
        };
        let present = |f: &Field| obj.get(&*f.name).is_some_and(|v| !v.is_null());
        match t.kind {
            Kind::Union => {
                let switch = match obj.get("SwitchField").and_then(Value::as_u64) {
                    Some(s) => s as usize,
                    None => t.fields.iter().position(present).map_or(0, |i| i + 1),
                };
                w.u32(switch as u32);
                if switch > 0 {
                    let f = t.fields.get(switch - 1).ok_or("SwitchField out of range")?;
                    self.write_value(obj.get(&*f.name), f.data_type, f.value_rank, w, depth)?;
                }
            }
            Kind::StructureWithOptionalFields => {
                let given = obj.get("EncodingMask").and_then(Value::as_u64);
                let mut mask = 0u32;
                for (bit, f) in t.fields.iter().filter(|f| f.optional).enumerate() {
                    let on = match given {
                        Some(m) => m & (1 << bit) != 0,
                        None => present(f),
                    };
                    if on {
                        mask |= 1 << bit;
                    }
                }
                w.u32(mask);
                let mut bit = 0;
                for f in t.fields.iter() {
                    if f.optional {
                        let on = mask & (1 << bit) != 0;
                        bit += 1;
                        if !on {
                            continue;
                        }
                    }
                    self.write_value(obj.get(&*f.name), f.data_type, f.value_rank, w, depth)?;
                }
            }
            _ => {
                for f in t.fields.iter() {
                    self.write_value(obj.get(&*f.name), f.data_type, f.value_rank, w, depth)?;
                }
            }
        }
        Ok(())
    }

    fn write_builtin(&self, builtin: u32, v: Option<&Value>, w: &mut Writer, depth: u32) -> JResult<()> {
        let bad = |what: &str| format!("invalid {what}");
        match builtin {
            1 => w.bool(v.and_then(Value::as_bool).unwrap_or(false)),
            2 => w.i8(int(v)?.try_into().map_err(|_| bad("SByte"))?),
            3 => w.u8(int(v)?.try_into().map_err(|_| bad("Byte"))?),
            4 => w.i16(int(v)?.try_into().map_err(|_| bad("Int16"))?),
            5 => w.u16(int(v)?.try_into().map_err(|_| bad("UInt16"))?),
            6 => w.i32(int(v)?.try_into().map_err(|_| bad("Int32"))?),
            7 => w.u32(int(v)?.try_into().map_err(|_| bad("UInt32"))?),
            8 => w.i64(int(v)?.try_into().map_err(|_| bad("Int64"))?),
            9 => w.u64(int(v)?.try_into().map_err(|_| bad("UInt64"))?),
            10 => w.f32(float(v)? as f32),
            11 => w.f64(float(v)?),
            12 => w.str(string(v)?),
            13 => w.i64(match string(v)? {
                Some(s) => parse_date_time(s)?,
                None => 0,
            }),
            14 => w.raw(&match string(v)? {
                Some(s) => parse_guid(s).ok_or_else(|| bad("Guid"))?,
                None => [0; 16],
            }),
            15 => match string(v)? {
                Some(s) => w.bytes(Some(&decode_base64(s).ok_or_else(|| bad("ByteString"))?)),
                None => w.bytes(None),
            },
            16 => w.bytes(string(v)?.map(str::as_bytes)),
            17 => w.node_id(&match string(v)? {
                Some(s) => self.node_id(s)?,
                None => NodeId::NULL,
            }),
            18 => w.expanded_node_id(&match string(v)? {
                Some(s) => self.expanded_node_id(s)?,
                None => ExpandedNodeId { node_id: NodeId::NULL, namespace_uri: None, server_index: 0 },
            }),
            19 => w.u32(status_code(v)?),
            20 => {
                let (ns, name) = match string(v)? {
                    Some(s) => self.qualified_name(s)?,
                    None => (0, None),
                };
                w.u16(ns);
                w.str(name);
            }
            21 => {
                let (locale, text) = match v {
                    Some(Value::Object(o)) => (
                        o.get("Locale").and_then(Value::as_str).filter(|s| !s.is_empty()),
                        o.get("Text").and_then(Value::as_str),
                    ),
                    Some(Value::String(s)) => (None, Some(s.as_str())),
                    None => (None, None),
                    Some(_) => return Err(bad("LocalizedText")),
                };
                w.u8(locale.map_or(0, |_| 1) | text.map_or(0, |_| 2));
                if let Some(l) = locale {
                    w.string(l);
                }
                if let Some(t) = text {
                    w.string(t);
                }
            }
            22 => self.write_extension_object(v, w, depth)?,
            23 => self.write_data_value(v, w, depth)?,
            24 => self.write_variant(v, w, depth)?,
            25 => self.write_diagnostic_info(v, w, depth)?,
            _ => return Err(format!("unsupported built-in type {builtin}")),
        }
        Ok(())
    }

    fn write_extension_object(&self, v: Option<&Value>, w: &mut Writer, depth: u32) -> JResult<()> {
        let Some(o) = v.and_then(Value::as_object) else {
            w.node_id(&NodeId::NULL);
            w.u8(0);
            return Ok(());
        };
        let id = eo_field(o, "TypeId").and_then(Value::as_str).ok_or("ExtensionObject without TypeId")?;
        let encoding = eo_field(o, "Encoding").and_then(Value::as_u64).unwrap_or(0);
        let body = eo_field(o, "Body").filter(|b| !b.is_null());
        if encoding != 0 {
            // Already encoded (ByteString or XmlElement): passed through.
            w.node_id(&self.node_id(id)?);
            w.u8(encoding as u8);
            let b = body.and_then(Value::as_str).ok_or("ExtensionObject without Body")?;
            match encoding {
                1 => w.bytes(Some(&decode_base64(b).ok_or("invalid ExtensionObject body")?)),
                _ => w.bytes(Some(b.as_bytes())),
            }
            return Ok(());
        }
        let t = self.message_type(id)?;
        let at = w.begin_extension_object(t.binary_encoding);
        self.write_structure(t, body, w, depth + 1)?;
        w.end_extension_object(at);
        Ok(())
    }

    fn write_variant(&self, v: Option<&Value>, w: &mut Writer, depth: u32) -> JResult<()> {
        let Some(o) = v.and_then(Value::as_object) else {
            w.u8(0);
            return Ok(());
        };
        let ty = o.get("UaType").and_then(Value::as_u64).unwrap_or(0) as u32;
        if ty == 0 {
            w.u8(0);
            return Ok(());
        }
        if ty > 25 {
            return Err("invalid Variant type".into());
        }
        let dims: Option<Vec<i32>> = o
            .get("Dimensions")
            .and_then(Value::as_array)
            .map(|d| d.iter().map(|x| x.as_i64().unwrap_or(0) as i32).collect());
        let value = o.get("Value");
        match value {
            Some(Value::Array(items)) => {
                w.u8(ty as u8 | 0x80 | if dims.is_some() { 0x40 } else { 0 });
                w.i32(items.len() as i32);
                for item in items {
                    self.write_builtin(ty, Some(item).filter(|i| !i.is_null()), w, depth + 1)?;
                }
                if let Some(d) = dims {
                    w.i32(d.len() as i32);
                    for x in d {
                        w.i32(x);
                    }
                }
            }
            _ => {
                w.u8(ty as u8);
                self.write_builtin(ty, value.filter(|v| !v.is_null()), w, depth + 1)?;
            }
        }
        Ok(())
    }

    fn write_data_value(&self, v: Option<&Value>, w: &mut Writer, depth: u32) -> JResult<()> {
        let Some(o) = v.and_then(Value::as_object) else {
            w.u8(0);
            return Ok(());
        };
        let has = |k: &str| o.get(k).is_some_and(|v| !v.is_null());
        let mut mask = 0u8;
        if has("UaType") {
            mask |= 0x01;
        }
        if has("Status") {
            mask |= 0x02;
        }
        if has("SourceTimestamp") {
            mask |= 0x04;
        }
        if has("ServerTimestamp") {
            mask |= 0x08;
        }
        if has("SourcePicoseconds") {
            mask |= 0x10;
        }
        if has("ServerPicoseconds") {
            mask |= 0x20;
        }
        w.u8(mask);
        if mask & 0x01 != 0 {
            self.write_variant(v, w, depth)?;
        }
        if mask & 0x02 != 0 {
            w.u32(status_code(o.get("Status"))?);
        }
        if mask & 0x04 != 0 {
            self.write_builtin(13, o.get("SourceTimestamp"), w, depth)?;
        }
        if mask & 0x10 != 0 {
            self.write_builtin(5, o.get("SourcePicoseconds"), w, depth)?;
        }
        if mask & 0x08 != 0 {
            self.write_builtin(13, o.get("ServerTimestamp"), w, depth)?;
        }
        if mask & 0x20 != 0 {
            self.write_builtin(5, o.get("ServerPicoseconds"), w, depth)?;
        }
        Ok(())
    }

    fn write_diagnostic_info(&self, v: Option<&Value>, w: &mut Writer, depth: u32) -> JResult<()> {
        let Some(o) = v.and_then(Value::as_object) else {
            w.u8(0);
            return Ok(());
        };
        let index = |k: &str| o.get(k).and_then(Value::as_i64).filter(|&i| i >= 0);
        let (sym, ns, locale, text) =
            (index("SymbolicId"), index("NamespaceUri"), index("Locale"), index("LocalizedText"));
        let info = o.get("AdditionalInfo").and_then(Value::as_str);
        let inner_code = o.get("InnerStatusCode").filter(|v| !v.is_null());
        let inner = o.get("InnerDiagnosticInfo").filter(|v| !v.is_null());
        let mut mask = 0u8;
        for (on, bit) in [
            (sym.is_some(), 0x01),
            (ns.is_some(), 0x02),
            (text.is_some(), 0x04),
            (locale.is_some(), 0x08),
            (info.is_some(), 0x10),
            (inner_code.is_some(), 0x20),
            (inner.is_some(), 0x40),
        ] {
            if on {
                mask |= bit;
            }
        }
        w.u8(mask);
        for x in [sym, ns, locale, text].into_iter().flatten() {
            w.i32(x as i32);
        }
        if let Some(s) = info {
            w.string(s);
        }
        if inner_code.is_some() {
            w.u32(status_code(inner_code)?);
        }
        if inner.is_some() {
            if depth > MAX_DEPTH {
                return Err("nested too deeply".into());
            }
            self.write_diagnostic_info(inner, w, depth + 1)?;
        }
        Ok(())
    }

    /// `i=1`, `ns=2;s=x`, `nsu=urn:x;s=y`.
    fn node_id(&self, s: &str) -> JResult<NodeId> {
        match s.strip_prefix("nsu=") {
            Some(rest) => {
                let (uri, id) = rest.split_once(';').ok_or_else(|| format!("invalid NodeId {s}"))?;
                let uri = percent_decode(uri);
                let ns = self
                    .namespaces
                    .iter()
                    .position(|u| **u == *uri)
                    .ok_or_else(|| format!("unknown namespace {uri}"))?;
                let id = NodeId::parse(id)?;
                Ok(with_namespace(id, ns as u16))
            }
            None => NodeId::parse(s),
        }
    }

    fn expanded_node_id(&self, s: &str) -> JResult<ExpandedNodeId> {
        let (server_index, rest) = match s.strip_prefix("svr=") {
            Some(r) => {
                let (n, rest) = r.split_once(';').ok_or_else(|| format!("invalid ExpandedNodeId {s}"))?;
                (n.parse().map_err(|_| format!("invalid ExpandedNodeId {s}"))?, rest)
            }
            None => (0, s),
        };
        // A namespace URI the server does not know stays a URI.
        if let Some(r) = rest.strip_prefix("nsu=") {
            if let Some((uri, id)) = r.split_once(';') {
                let uri = percent_decode(uri);
                if !self.namespaces.iter().any(|u| **u == *uri) {
                    return Ok(ExpandedNodeId {
                        node_id: NodeId::parse(id)?,
                        namespace_uri: Some(uri.into()),
                        server_index,
                    });
                }
            }
        }
        Ok(ExpandedNodeId { node_id: self.node_id(rest)?, namespace_uri: None, server_index })
    }

    /// `Name`, `nsu=urn:x;Name` or `2:Name`.
    fn qualified_name<'s>(&self, s: &'s str) -> JResult<(u16, Option<&'s str>)> {
        if let Some(rest) = s.strip_prefix("nsu=") {
            let (uri, name) = rest.split_once(';').ok_or_else(|| format!("invalid QualifiedName {s}"))?;
            let uri = percent_decode(uri);
            let ns =
                self.namespaces.iter().position(|u| **u == *uri).ok_or_else(|| format!("unknown namespace {uri}"))?;
            return Ok((ns as u16, Some(name)));
        }
        if let Some((n, name)) = s.split_once(':') {
            if let Ok(ns) = n.parse::<u16>() {
                return Ok((ns, Some(name)));
            }
        }
        Ok((0, Some(s)))
    }

    // ------------------------------------------------- binary -> JSON

    /// A binary message (encoding NodeId, then body) to its JSON form:
    /// `{"TypeId": <data type>, "Body": {...}}`.
    pub fn message_to_json(&self, binary: &[u8]) -> JResult<Vec<u8>> {
        let mut r = Reader::new(binary);
        let id = r.node_id().map_err(|_| "invalid message")?;
        let t = match id {
            NodeId::Numeric(0, n) => self.types.by_encoding(n),
            _ => None,
        }
        .ok_or_else(|| format!("unknown message type {id}"))?;
        let body = self.read_structure(t, &mut r, 0)?;
        let mut m = Map::new();
        m.insert("TypeId".into(), Value::String(format!("i={}", t.id)));
        m.insert("Body".into(), body);
        serde_json::to_vec(&Value::Object(m)).map_err(|e| e.to_string())
    }

    fn read_value(&self, r: &mut Reader, data_type: u32, rank: i32, depth: u32) -> JResult<Option<Value>> {
        if depth > MAX_DEPTH {
            return Err("nested too deeply".into());
        }
        if rank >= 0 {
            let n = r.i32().map_err(dec)?;
            if n < 0 {
                return Ok(None);
            }
            if n as usize > r.remaining() {
                return Err("invalid array length".into());
            }
            let mut items = Vec::with_capacity(n as usize);
            for _ in 0..n {
                items.push(self.read_scalar(r, data_type, depth + 1)?.unwrap_or(Value::Null));
            }
            return Ok(Some(Value::Array(items)));
        }
        self.read_scalar(r, data_type, depth)
    }

    fn read_scalar(&self, r: &mut Reader, data_type: u32, depth: u32) -> JResult<Option<Value>> {
        if let Some(t) = self.types.by_id(data_type) {
            match t.kind {
                Kind::Structure | Kind::StructureWithOptionalFields | Kind::Union => {
                    return self.read_structure(t, r, depth + 1).map(Some)
                }
                Kind::Enumeration => {
                    let v = r.i32().map_err(dec)?;
                    return Ok((v != 0).then(|| v.into()));
                }
                Kind::Other => {}
            }
        }
        let builtin = if data_type == 29 { 6 } else { self.types.builtin(data_type) };
        self.read_builtin(r, builtin, depth)
    }

    fn read_structure(&self, t: &DataType, r: &mut Reader, depth: u32) -> JResult<Value> {
        let mut m = Map::new();
        match t.kind {
            Kind::Union => {
                let switch = r.u32().map_err(dec)? as usize;
                if switch > 0 {
                    let f = t.fields.get(switch - 1).ok_or("invalid union switch")?;
                    m.insert("SwitchField".into(), switch.into());
                    let v = self.read_value(r, f.data_type, f.value_rank, depth)?;
                    m.insert(f.name.to_string(), v.unwrap_or(Value::Null));
                }
            }
            Kind::StructureWithOptionalFields => {
                let mask = r.u32().map_err(dec)?;
                m.insert("EncodingMask".into(), mask.into());
                let mut bit = 0;
                for f in t.fields.iter() {
                    if f.optional {
                        let on = mask & (1 << bit) != 0;
                        bit += 1;
                        if !on {
                            continue;
                        }
                    }
                    if let Some(v) = self.read_value(r, f.data_type, f.value_rank, depth)? {
                        m.insert(f.name.to_string(), v);
                    }
                }
            }
            _ => {
                for f in t.fields.iter() {
                    if let Some(v) = self.read_value(r, f.data_type, f.value_rank, depth)? {
                        m.insert(f.name.to_string(), v);
                    }
                }
            }
        }
        Ok(Value::Object(m))
    }

    /// The JSON value of a built-in, `None` for the default value (left
    /// out of a structure, as the compact encoding does).
    fn read_builtin(&self, r: &mut Reader, builtin: u32, depth: u32) -> JResult<Option<Value>> {
        fn num<T: Into<Number> + PartialEq + Default>(v: T) -> Option<Value> {
            (v != T::default()).then(|| Value::Number(v.into()))
        }
        Ok(match builtin {
            1 => r.bool().map_err(dec)?.then_some(Value::Bool(true)),
            2 => num(r.i8().map_err(dec)?),
            3 => num(r.u8().map_err(dec)?),
            4 => num(r.i16().map_err(dec)?),
            5 => num(r.u16().map_err(dec)?),
            6 => num(r.i32().map_err(dec)?),
            7 => num(r.u32().map_err(dec)?),
            8 => Some(r.i64().map_err(dec)?).filter(|&v| v != 0).map(|v| Value::String(v.to_string())),
            9 => Some(r.u64().map_err(dec)?).filter(|&v| v != 0).map(|v| Value::String(v.to_string())),
            10 => float_value(r.f32().map_err(dec)? as f64),
            11 => float_value(r.f64().map_err(dec)?),
            12 => r.str().map_err(dec)?.map(|s| Value::String(s.into())),
            13 => {
                let t = r.i64().map_err(dec)?;
                (t != 0).then(|| Value::String(format_date_time(t)))
            }
            14 => {
                let g: [u8; 16] = r.take(16).map_err(dec)?.try_into().unwrap();
                (g != [0; 16]).then(|| Value::String(format_guid(&g)))
            }
            15 => r.bytes().map_err(dec)?.map(|b| Value::String(encode_base64(b))),
            16 => r.bytes().map_err(dec)?.map(|b| Value::String(String::from_utf8_lossy(b).into())),
            17 => {
                let id = r.node_id().map_err(dec)?;
                (id != NodeId::NULL).then(|| Value::String(self.node_id_string(&id)))
            }
            18 => {
                let e = r.expanded_node_id().map_err(dec)?;
                (e.node_id != NodeId::NULL || e.namespace_uri.is_some() || e.server_index != 0)
                    .then(|| Value::String(self.expanded_node_id_string(&e)))
            }
            19 => {
                let code = r.u32().map_err(dec)?;
                (code != 0).then(|| {
                    let mut m = Map::new();
                    m.insert("Code".into(), code.into());
                    Value::Object(m)
                })
            }
            20 => {
                let ns = r.u16().map_err(dec)?;
                let name = r.str().map_err(dec)?;
                match (ns, name) {
                    (0, None) => None,
                    (0, Some(n)) => Some(Value::String(n.into())),
                    (ns, n) => Some(Value::String(match self.namespaces.get(ns as usize) {
                        Some(uri) => format!("nsu={};{}", percent_encode(uri), n.unwrap_or("")),
                        None => format!("{ns}:{}", n.unwrap_or("")),
                    })),
                }
            }
            21 => {
                let mask = r.u8().map_err(dec)?;
                let mut m = Map::new();
                if mask & 1 != 0 {
                    if let Some(l) = r.str().map_err(dec)?.filter(|l| !l.is_empty()) {
                        m.insert("Locale".into(), Value::String(l.into()));
                    }
                }
                if mask & 2 != 0 {
                    if let Some(t) = r.str().map_err(dec)? {
                        m.insert("Text".into(), Value::String(t.into()));
                    }
                }
                (!m.is_empty()).then_some(Value::Object(m))
            }
            22 => self.read_extension_object(r, depth)?,
            23 => self.read_data_value(r, depth)?,
            24 => self.read_variant(r, depth)?.map(Value::Object),
            25 => self.read_diagnostic_info(r, depth)?,
            _ => return Err(format!("unsupported built-in type {builtin}")),
        })
    }

    fn read_extension_object(&self, r: &mut Reader, depth: u32) -> JResult<Option<Value>> {
        let id = r.node_id().map_err(dec)?;
        let encoding = r.u8().map_err(dec)?;
        if encoding == 0 {
            return Ok(None);
        }
        let body = r.bytes().map_err(dec)?.unwrap_or(&[]);
        let mut m = Map::new();
        let known = match (&id, encoding) {
            (NodeId::Numeric(0, n), 1) => self.types.by_encoding(*n),
            _ => None,
        };
        if let Some(t) = known {
            let mut br = Reader::new(body);
            let v = self.read_structure(t, &mut br, depth + 1)?;
            m.insert("TypeId".into(), Value::String(format!("i={}", t.id)));
            m.insert("Body".into(), v);
        } else {
            m.insert("TypeId".into(), Value::String(self.node_id_string(&id)));
            m.insert("Encoding".into(), encoding.into());
            let b = if encoding == 1 { encode_base64(body) } else { String::from_utf8_lossy(body).into() };
            m.insert("Body".into(), Value::String(b));
        }
        Ok(Some(Value::Object(m)))
    }

    /// The fields of a Variant (`UaType`, `Value`, `Dimensions`), `None`
    /// when empty.
    fn read_variant(&self, r: &mut Reader, depth: u32) -> JResult<Option<Map<String, Value>>> {
        if depth > MAX_DEPTH {
            return Err("nested too deeply".into());
        }
        let mask = r.u8().map_err(dec)?;
        let ty = (mask & 0x3F) as u32;
        if ty == 0 {
            return Ok(None);
        }
        let mut m = Map::new();
        m.insert("UaType".into(), ty.into());
        if mask & 0x80 != 0 {
            let n = r.i32().map_err(dec)?;
            let mut items = Vec::new();
            if n > 0 {
                if n as usize > r.remaining() {
                    return Err("invalid array length".into());
                }
                for _ in 0..n {
                    items.push(self.read_builtin_element(r, ty, depth + 1)?);
                }
            }
            m.insert("Value".into(), Value::Array(items));
            if mask & 0x40 != 0 {
                let d = r.i32().map_err(dec)?.max(0);
                let mut dims = Vec::new();
                for _ in 0..d {
                    dims.push(Value::from(r.i32().map_err(dec)?));
                }
                m.insert("Dimensions".into(), Value::Array(dims));
            }
        } else if let Some(v) = self.read_builtin(r, ty, depth + 1)? {
            m.insert("Value".into(), v);
        } else {
            m.insert("Value".into(), default_value(ty));
        }
        Ok(Some(m))
    }

    /// An array element keeps its default value (arrays are positional).
    fn read_builtin_element(&self, r: &mut Reader, ty: u32, depth: u32) -> JResult<Value> {
        Ok(match self.read_builtin(r, ty, depth)? {
            Some(v) => v,
            None => default_value(ty),
        })
    }

    fn read_data_value(&self, r: &mut Reader, depth: u32) -> JResult<Option<Value>> {
        let mask = r.u8().map_err(dec)?;
        let mut m = Map::new();
        if mask & 0x01 != 0 {
            if let Some(v) = self.read_variant(r, depth + 1)? {
                m.extend(v);
            }
        }
        if mask & 0x02 != 0 {
            if let Some(s) = self.read_builtin(r, 19, depth)? {
                m.insert("Status".into(), s);
            }
        }
        for (bit, ty, name) in [
            (0x04, 13, "SourceTimestamp"),
            (0x10, 5, "SourcePicoseconds"),
            (0x08, 13, "ServerTimestamp"),
            (0x20, 5, "ServerPicoseconds"),
        ] {
            if mask & bit != 0 {
                if let Some(v) = self.read_builtin(r, ty, depth)? {
                    m.insert(name.into(), v);
                }
            }
        }
        Ok((!m.is_empty()).then_some(Value::Object(m)))
    }

    fn read_diagnostic_info(&self, r: &mut Reader, depth: u32) -> JResult<Option<Value>> {
        if depth > MAX_DEPTH {
            return Err("nested too deeply".into());
        }
        let mask = r.u8().map_err(dec)?;
        let mut m = Map::new();
        for (bit, name) in [(0x01, "SymbolicId"), (0x02, "NamespaceUri"), (0x08, "Locale"), (0x04, "LocalizedText")] {
            if mask & bit != 0 {
                m.insert(name.into(), r.i32().map_err(dec)?.into());
            }
        }
        if mask & 0x10 != 0 {
            if let Some(s) = r.str().map_err(dec)? {
                m.insert("AdditionalInfo".into(), Value::String(s.into()));
            }
        }
        if mask & 0x20 != 0 {
            if let Some(s) = self.read_builtin(r, 19, depth)? {
                m.insert("InnerStatusCode".into(), s);
            }
        }
        if mask & 0x40 != 0 {
            if let Some(i) = self.read_diagnostic_info(r, depth + 1)? {
                m.insert("InnerDiagnosticInfo".into(), i);
            }
        }
        Ok((!m.is_empty()).then_some(Value::Object(m)))
    }

    fn node_id_string(&self, id: &NodeId) -> String {
        let ns = id.namespace();
        match self.namespaces.get(ns as usize).filter(|_| ns != 0) {
            Some(uri) => format!("nsu={};{}", percent_encode(uri), identifier(id)),
            None if ns == 0 => identifier(id),
            None => format!("ns={ns};{}", identifier(id)),
        }
    }

    fn expanded_node_id_string(&self, e: &ExpandedNodeId) -> String {
        let id = match &e.namespace_uri {
            Some(uri) => format!("nsu={};{}", percent_encode(uri), identifier(&e.node_id)),
            None => self.node_id_string(&e.node_id),
        };
        match e.server_index {
            0 => id,
            s => format!("svr={s};{id}"),
        }
    }
}

/// A field of an ExtensionObject: Part 6 §5.4.2.16 names them TypeId,
/// Encoding and Body; §5.4.1 also mentions UaTypeId, so the `Ua` prefixed
/// names are accepted too.
fn eo_field<'v>(o: &'v Map<String, Value>, name: &str) -> Option<&'v Value> {
    o.get(name).or_else(|| match name {
        "TypeId" => o.get("UaTypeId"),
        "Encoding" => o.get("UaEncoding"),
        _ => o.get("UaBody"),
    })
}

fn dec(_: crate::codec::DecodeError) -> String {
    "invalid binary encoding".into()
}

/// The identifier part of a NodeId (`i=`, `s=`, `g=`, `b=`).
fn identifier(id: &NodeId) -> String {
    match id {
        NodeId::Numeric(_, v) => format!("i={v}"),
        NodeId::String(_, s) => format!("s={s}"),
        NodeId::Guid(_, g) => format!("g={}", format_guid(g)),
        NodeId::Opaque(_, b) => format!("b={}", encode_base64(b)),
    }
}

fn with_namespace(id: NodeId, ns: u16) -> NodeId {
    match id {
        NodeId::Numeric(_, v) => NodeId::Numeric(ns, v),
        NodeId::String(_, v) => NodeId::String(ns, v),
        NodeId::Guid(_, v) => NodeId::Guid(ns, v),
        NodeId::Opaque(_, v) => NodeId::Opaque(ns, v),
    }
}

/// `;` and `%` are escaped in a namespace URI of a string NodeId.
fn percent_encode(uri: &str) -> String {
    uri.replace('%', "%25").replace(';', "%3B")
}

fn percent_decode(uri: &str) -> String {
    uri.replace("%3B", ";").replace("%3b", ";").replace("%25", "%")
}

fn int(v: Option<&Value>) -> JResult<i128> {
    match v {
        None => Ok(0),
        Some(Value::Number(n)) => n
            .as_i64()
            .map(i128::from)
            .or_else(|| n.as_u64().map(i128::from))
            .or_else(|| n.as_f64().filter(|f| f.fract() == 0.0).map(|f| f as i128))
            .ok_or_else(|| format!("invalid integer {n}")),
        Some(Value::String(s)) => s.trim().parse().map_err(|_| format!("invalid integer {s}")),
        Some(Value::Bool(b)) => Ok(*b as i128),
        Some(other) => Err(format!("invalid integer {other}")),
    }
}

fn float(v: Option<&Value>) -> JResult<f64> {
    match v {
        None => Ok(0.0),
        Some(Value::Number(n)) => n.as_f64().ok_or_else(|| format!("invalid number {n}")),
        Some(Value::String(s)) => match s.as_str() {
            "NaN" => Ok(f64::NAN),
            "Infinity" => Ok(f64::INFINITY),
            "-Infinity" => Ok(f64::NEG_INFINITY),
            s => s.parse().map_err(|_| format!("invalid number {s}")),
        },
        Some(other) => Err(format!("invalid number {other}")),
    }
}

fn float_value(f: f64) -> Option<Value> {
    if f == 0.0 && f.is_sign_positive() {
        return None;
    }
    Some(match Number::from_f64(f) {
        Some(n) => Value::Number(n),
        None if f.is_nan() => Value::String("NaN".into()),
        None if f > 0.0 => Value::String("Infinity".into()),
        None => Value::String("-Infinity".into()),
    })
}

fn string(v: Option<&Value>) -> JResult<Option<&str>> {
    match v {
        None => Ok(None),
        Some(Value::String(s)) => Ok(Some(s)),
        Some(other) => Err(format!("a string was expected, not {other}")),
    }
}

fn status_code(v: Option<&Value>) -> JResult<u32> {
    match v {
        None | Some(Value::Null) => Ok(0),
        Some(Value::Object(o)) => Ok(int(o.get("Code"))? as u32),
        Some(v) => Ok(int(Some(v))? as u32),
    }
}

/// An enumeration: a number, `Name_1`, or a name.
fn enum_value(t: &DataType, v: Option<&Value>) -> JResult<i32> {
    match v {
        Some(Value::String(s)) => {
            if let Some((_, n)) = s.rsplit_once('_') {
                if let Ok(n) = n.parse() {
                    return Ok(n);
                }
            }
            if let Ok(n) = s.parse() {
                return Ok(n);
            }
            t.values
                .iter()
                .find(|(name, _)| **name == **s)
                .map(|&(_, v)| v as i32)
                .ok_or_else(|| format!("invalid {} value {s}", t.name))
        }
        v => Ok(int(v)? as i32),
    }
}

/// The JSON value of a built-in's default (array elements, Variant values).
fn default_value(ty: u32) -> Value {
    match ty {
        1 => Value::Bool(false),
        2..=7 | 10 | 11 => Value::from(0),
        8 | 9 => Value::String("0".into()),
        13 => Value::String("0001-01-01T00:00:00Z".into()),
        14 => Value::String(format_guid(&[0; 16])),
        _ => Value::Null,
    }
}

/// ISO 8601 (RFC 3339) to 100 ns ticks since 1601.
fn parse_date_time(s: &str) -> JResult<i64> {
    use time::format_description::well_known::Rfc3339;
    let t = time::OffsetDateTime::parse(s, &Rfc3339).map_err(|_| format!("invalid DateTime {s}"))?;
    let ticks = t.unix_timestamp_nanos() / 100 + UNIX_EPOCH_TICKS as i128;
    Ok(ticks.clamp(0, i64::MAX as i128) as i64)
}

fn format_date_time(ticks: i64) -> String {
    use time::format_description::well_known::Rfc3339;
    let nanos = (ticks as i128 - UNIX_EPOCH_TICKS as i128) * 100;
    match time::OffsetDateTime::from_unix_timestamp_nanos(nanos) {
        Ok(t) if t.year() <= 9999 => t.format(&Rfc3339).unwrap_or_default(),
        _ => "9999-12-31T23:59:59Z".into(),
    }
}

pub fn encode_base64(b: &[u8]) -> String {
    const A: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(b.len().div_ceil(3) * 4);
    for c in b.chunks(3) {
        let n = (c[0] as u32) << 16 | (*c.get(1).unwrap_or(&0) as u32) << 8 | *c.get(2).unwrap_or(&0) as u32;
        for i in 0..4 {
            if i <= c.len() {
                out.push(A[(n >> (18 - 6 * i) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn round_trip(t: &Transcoder, json: &str) -> Value {
        let mut bin = Vec::new();
        t.message_to_binary(json.as_bytes(), &mut bin).unwrap_or_else(|e| panic!("{e}: {json}"));
        serde_json::from_slice(&t.message_to_json(&bin).unwrap()).unwrap()
    }

    #[test]
    fn types_table() {
        let t = Types::get();
        let read = t.by_id(629).unwrap();
        assert_eq!(&*read.name, "ReadRequest");
        assert_eq!(read.binary_encoding, 631);
        assert_eq!(t.by_encoding(631).unwrap().id, 629);
        // Subtypes of built-in types resolve to them (Duration -> Double).
        assert_eq!(t.builtin(290), 11);
    }

    /// Every built-in type survives JSON -> binary -> JSON.
    #[test]
    fn builtins_round_trip() {
        let ns: Vec<Arc<str>> = vec!["http://opcfoundation.org/UA/".into(), "urn:a".into(), "urn:b".into()];
        let t = Transcoder::new(&ns);
        let values = [
            r#"{"UaType":1,"Value":true}"#,
            r#"{"UaType":2,"Value":-5}"#,
            r#"{"UaType":3,"Value":200}"#,
            r#"{"UaType":4,"Value":-300}"#,
            r#"{"UaType":5,"Value":60000}"#,
            r#"{"UaType":6,"Value":-70000}"#,
            r#"{"UaType":7,"Value":4000000000}"#,
            r#"{"UaType":8,"Value":"-9007199254740993"}"#,
            r#"{"UaType":9,"Value":"18446744073709551615"}"#,
            r#"{"UaType":10,"Value":1.5}"#,
            r#"{"UaType":11,"Value":"NaN"}"#,
            r#"{"UaType":11,"Value":"-Infinity"}"#,
            r#"{"UaType":12,"Value":"héllo"}"#,
            r#"{"UaType":13,"Value":"2026-11-25T21:00:00.1234567Z"}"#,
            r#"{"UaType":14,"Value":"72962b91-fa75-4ae6-8d28-b404dc7daf63"}"#,
            r#"{"UaType":15,"Value":"AAECAwQ="}"#,
            r#"{"UaType":16,"Value":"<a>b</a>"}"#,
            r#"{"UaType":17,"Value":"nsu=urn:b;s=x;y"}"#,
            r#"{"UaType":17,"Value":"g=72962b91-fa75-4ae6-8d28-b404dc7daf63"}"#,
            r#"{"UaType":18,"Value":"svr=1;nsu=urn:other;b=AAE="}"#,
            r#"{"UaType":19,"Value":{"Code":2155085824}}"#,
            r#"{"UaType":20,"Value":"nsu=urn:a;Name"}"#,
            r#"{"UaType":21,"Value":{"Locale":"fr","Text":"bonjour"}}"#,
            r#"{"UaType":22,"Value":{"TypeId":"i=884","Body":{"Low":-1.5,"High":2.5}}}"#,
            r#"{"UaType":6,"Value":[1,2,3,4,5,6],"Dimensions":[2,3]}"#,
            r#"{"UaType":12,"Value":["a",null,"c"]}"#,
        ];
        for v in values {
            let json = format!(
                r#"{{"TypeId":"i=671","Body":{{"RequestHeader":{{}},"NodesToWrite":[{{"NodeId":"i=1","AttributeId":13,"Value":{v}}}]}}}}"#
            );
            let out = round_trip(&t, &json);
            let got = &out["Body"]["NodesToWrite"][0]["Value"];
            let want: Value = serde_json::from_str(v).unwrap();
            assert_eq!(got, &want, "{v}");
        }
    }

    /// Optional fields, unions, enumerations and DiagnosticInfo.
    #[test]
    fn structures_round_trip() {
        let t = Transcoder::new(&[]);
        let json = r#"{"TypeId":"i=395","Body":{"ResponseHeader":{"Timestamp":"2026-01-01T00:00:00Z",
            "ServiceResult":{"Code":2147549184},
            "ServiceDiagnostics":{"SymbolicId":1,"LocalizedText":2,"AdditionalInfo":"x",
                "InnerStatusCode":{"Code":2147483648},"InnerDiagnosticInfo":{"AdditionalInfo":"y"}},
            "StringTable":["a","b","c"]}}}"#;
        let out = round_trip(&t, json);
        let want: Value = serde_json::from_str(json).unwrap();
        assert_eq!(out, want);
        // Enumerations are numbers; "Name_N" is accepted.
        let json =
            r#"{"TypeId":"i=629","Body":{"RequestHeader":{},"TimestampsToReturn":"Neither_3","NodesToRead":[]}}"#;
        let out = round_trip(&t, json);
        assert_eq!(out["Body"]["TimestampsToReturn"], 3);
    }

    #[test]
    fn errors() {
        let t = Transcoder::new(&[]);
        let mut bin = Vec::new();
        assert!(t.message_to_binary(b"[]", &mut bin).is_err());
        assert!(t.message_to_binary(br#"{"TypeId":"i=1","Body":{}}"#, &mut bin).is_err());
        assert!(t.message_to_binary(br#"{"TypeId":"i=629","Body":{"MaxAge":"x"}}"#, &mut bin).is_err());
    }
}
